-- Certification (plan Premium uniquement), boutique officielle renommée, rayons et catégories du catalogue.
ALTER TABLE plans ADD COLUMN certified BOOLEAN NOT NULL DEFAULT FALSE;
UPDATE plans SET certified = TRUE, features = ARRAY['Produits illimités','5 photos par produit','Commission de 2 %','Badge « Vendeur certifié Mwinda »','Mise en avant prioritaire'] WHERE code = 'premium';
UPDATE shops SET name = 'Mwinda Market', slug = 'mwinda-market' WHERE id = '01OFFICIALSHOP000000000000';

WITH t AS (SELECT (e.v->>0) AS slug, (e.v->>1) AS name, e.v->2 AS cats, (e.i - 1) AS sort FROM jsonb_array_elements('[["vetements","Vêtements et Accessoires",["Robes","Chemises","Pantalons","Chaussures","T-shirts et polos","Vestes et manteaux","Pagnes et tissus africains","Tenues traditionnelles","Sous-vêtements","Vêtements enfants","Casquettes et chapeaux","Sacs et maroquinerie","Ceintures et écharpes"]],["electronique","Électronique grand public",["Smartphone","Tablette","Ordinateur","Télévision","Audio","Appareil photo","Montre connectée","Écouteurs et casques","Chargeurs et câbles","Batteries externes","Accessoires téléphone","Drones","Consoles et jeux vidéo","Caméras de surveillance"]],["sport","Sports et Loisirs",["Football","Fitness et musculation","Cyclisme","Camping et randonnée","Pêche","Sports de combat","Vêtements de sport","Jeux et jouets","Instruments de musique"]],["bijoux","Bijoux, Lunettes et Montres",["Bijoux fantaisie","Bijoux en or et argent","Montres","Lunettes de soleil","Lunettes de vue","Perles et pierres","Colliers et bracelets"]],["emballage","Emballage et Impression",["Cartons et boîtes","Sacs en plastique et papier","Étiquettes et autocollants","Impression sur textile","Cartes de visite et flyers","Films et rubans adhésifs","Bouteilles et bocaux"]],["maison","Maison et Jardin",["Meubles","Literie et linge de maison","Décoration","Cuisine et ustensiles","Vaisselle","Rangement","Jardinage","Matelas","Tapis et rideaux"]],["vetements-sport","Vêtements de sport et plein air",["Maillots","Survêtements","Chaussures de sport","Vestes de pluie","Équipement de randonnée","Tenues de yoga"]],["beaute","Beauté et Soins personnels",["Maquillage","Soins de la peau","Soins des cheveux","Perruques et extensions","Parfums","Savons et huiles naturelles","Ongles et manucure","Hygiène","Matériel de coiffure"]],["sante","Santé et Médical",["Matériel médical","Tensiomètres et thermomètres","Masques et gants","Compléments alimentaires","Mobilité et orthopédie","Premiers secours"]],["cadeaux","Cadeaux et Artisanat",["Artisanat africain","Sculptures et masques","Paniers et vannerie","Cadeaux d''entreprise","Fêtes et mariages","Souvenirs"]],["animaux","Animaux et Accessoires",["Nourriture pour animaux","Cages et abris","Colliers et laisses","Soins vétérinaires","Jouets pour animaux"]],["bureau","Fournitures scolaires et de bureau",["Cahiers et papeterie","Stylos et crayons","Sacs d''école","Uniformes scolaires","Mobilier de bureau","Matériel de classe","Calculatrices"]],["imprimantes","Imprimantes et Scanners",["Imprimantes","Scanners","Cartouches et toners","Papier d''impression","Photocopieuses"]],["machines","Machines industrielles",["Machines agricoles","Machines de transformation alimentaire","Machines de construction","Machines à coudre","Compresseurs et pompes","Moulins et broyeurs","Équipement de boulangerie"]],["electromenager","Électroménager",["Réfrigérateurs et congélateurs","Machines à laver","Climatiseurs et ventilateurs","Cuisinières et fours","Mixeurs et blenders","Fers à repasser","Chauffe-eau","Aspirateurs"]],["auto-outils","Fournitures et outils automobiles",["Outils de garage","Huiles et lubrifiants","Accessoires intérieurs","Pneus et jantes","Batteries de voiture","Produits d''entretien auto"]],["pieces-auto","Pièces et accessoires auto",["Pièces moteur","Freins et suspensions","Éclairage auto","Pièces de carrosserie","Pièces de moto","Autoradios et GPS"]],["outils","Outils et quincaillerie",["Outils à main","Outils électriques","Serrures et cadenas","Visserie et fixations","Peinture et vernis","Échelles et échafaudages","Soudure"]],["energie","Énergies renouvelables",["Panneaux solaires","Onduleurs","Batteries solaires","Lampadaires solaires","Kits solaires domestiques","Régulateurs de charge","Groupes électrogènes"]],["securite","Sécurité et Protection",["Alarmes et détecteurs","Vidéosurveillance","Extincteurs","Équipement de protection individuelle","Coffres-forts","Chaussures et casques de sécurité"]],["manutention","Manutention",["Chariots et diables","Palettes","Rayonnages","Équipement de levage","Chariots élévateurs"]],["instruments","Instruments de test et de mesure",["Multimètres","Balances et pèse-personnes","Instruments de mesure de distance","Thermomètres industriels","Équipement de laboratoire"]],["transmission","Transmission mécanique",["Roulements","Courroies et chaînes","Engrenages","Moteurs électriques","Réducteurs"]],["composants","Composants électroniques",["Circuits intégrés","Résistances et condensateurs","Cartes Arduino et capteurs","Écrans et afficheurs","Câbles et connecteurs","Piles et batteries"]],["transport","Véhicules et Transport",["Motos","Tricycles","Vélos","Voitures d''occasion","Camions et remorques","Scooters électriques","Bateaux et pirogues"]],["agriculture","Agriculture, Alimentation et Boissons",["Céréales et farines","Fruits et légumes","Café et thé","Huiles et épices","Viandes et poissons","Boissons","Semences et engrais","Matériel agricole","Produits transformés"]],["construction","Construction et Immobilier",["Ciment","Fer à béton","Carrelage","Tôles et toitures","Briques et blocs","Portes et fenêtres","Sanitaires et plomberie","Électricité du bâtiment","Bois de construction","Sable et gravier"]],["textile","Textiles et Cuir",["Tissus","Cuir et peaux","Fil et mercerie","Wax et pagnes","Dentelle","Fermetures et boutons"]],["chaussures","Chaussures et Accessoires",["Chaussures homme","Chaussures femme","Chaussures enfant","Sandales et tongs","Bottes","Accessoires de chaussures"]],["bagages","Bagages, Sacs et Cases",["Valises","Sacs à dos","Sacs à main","Sacs de voyage","Pochettes et portefeuilles"]],["mere-enfant","Mère et Enfant",["Vêtements bébé","Poussettes","Jouets éducatifs","Lait et aliments bébé","Couches","Chaises et lits bébé"]],["jeux","Jeux, Jouets et Passe-temps",["Jouets","Puzzles et jeux de société","Poupées","Véhicules télécommandés","Collections"]],["telecom","Téléphonie et Télécommunications",["Routeurs et modems","Antennes","Téléphones basiques","Pièces de téléphone","Talkies-walkies"]],["informatique","Ordinateurs et Réseaux",["Ordinateurs portables","Ordinateurs de bureau","Écrans","Claviers et souris","Disques durs et clés USB","Switchs et câbles réseau","Logiciels"]],["eclairage","Éclairage",["Ampoules LED","Lampes de bureau","Lampes torches","Projecteurs","Guirlandes lumineuses","Lustres"]],["evenement","Événementiel et Fêtes",["Décorations de fête","Sonorisation","Chaises et tables location","Bâches et tentes","Costumes et déguisements"]],["education","Éducation et Formation",["Livres","Matériel pédagogique","Cours en ligne","Kits de robotique","Fournitures d''artiste"]],["services","Services professionnels",["Impression et design","Livraison et logistique","Installation et réparation","Photographie et vidéo","Traduction"]],["autres","Autres produits",["Divers"]]]'::jsonb) WITH ORDINALITY AS e(v, i)),
dep AS (
  INSERT INTO departments(id, slug, name, sort)
  SELECT '0009' || upper(substr(md5(random()::text || clock_timestamp()::text || slug), 1, 22)), slug, name, sort FROM t
  ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, sort = EXCLUDED.sort
  RETURNING id, slug
)
INSERT INTO categories(id, department_id, slug, name, sort)
SELECT '0009' || upper(substr(md5(random()::text || clock_timestamp()::text || dep.slug || c.name), 1, 22)), dep.id,
       left(dep.slug || '-' || trim(both '-' from regexp_replace(lower(translate(c.name, 'àâäçéèêëîïôöùûüÿœ', 'aaaceeeeiioouuuyo')), '[^a-z0-9]+', '-', 'g')), 80), c.name, (c.i - 1)
FROM dep JOIN t ON t.slug = dep.slug, jsonb_array_elements_text(t.cats) WITH ORDINALITY AS c(name, i)
WHERE NOT EXISTS (SELECT 1 FROM categories x WHERE x.department_id = dep.id AND x.name = c.name);

-- Nombre de produits actifs par rayon et par catégorie (lu par l'administration).
CREATE VIEW catalogue_counts AS
SELECT d.slug AS department, d.name AS department_name, c.name AS category,
       (SELECT count(*) FROM products p WHERE p.status = 'active' AND p.department = d.slug AND p.category = c.name) AS products
FROM departments d JOIN categories c ON c.department_id = d.id;
